						SAL <= ROM3(VPOS);
						PIX <= SAL(HPOS);
					END IF;
					IF PIX = '0' THEN
						COLOR <= 0;
					ELSE
						COLOR <= 1;
					END IF;
				ELSE
						COLOR <= 2;
				END IF;
			END IF;
		END IF;
	END PROCESS;
	
	PROCESS(CLK)
	BEGIN
		IF RISING_EDGE (CLK) THEN
			IF AUX = 0 THEN
				CLK2 <= NOT CLK2;
				AUX <= 1249999;
			ELSE
				AUX <= AUX - 1;
			END IF;
		END IF;
	END PROCESS;
	
	PROCESS(CLK2)
	BEGIN
		IF FALLING_EDGE(CLK2) THEN
			IF CONTA = 2 THEN
				CONTA <= 0;
			ELSE
				CONTA <= CONTA + 1;
			END IF;
		END IF;
	END PROCESS;
	
					
	WITH COLOR SELECT
		RGB <= "001" WHEN 0,
		       "011" WHEN 1,
				 "000" WHEN OTHERS;		
	
END BEAS;
